add_filter( 'woocommerce_available_payment_gateways', 'perfectpixel_gateway_by_user_role' );

function perfectpixel_gateway_by_user_role( $gateways ) {
	if ( is_admin() ) {
		return $gateways;
	}
	// Role => gateway IDs hidden for that role.
	$hide_for = array(
		'guest' => array( 'cod' ),
	);
	// Gateway ID => roles that can see it (everyone else does not).
	$only_for = array(
		'cheque' => array( 'wholesale_customer', 'administrator' ),
	);

	$user  = wp_get_current_user();
	$roles = $user->exists() ? (array) $user->roles : array( 'guest' );

	foreach ( $roles as $role ) {
		foreach ( $hide_for[ $role ] ?? array() as $id ) {
			unset( $gateways[ $id ] );
		}
	}
	foreach ( $only_for as $id => $allowed_roles ) {
		if ( ! array_intersect( $roles, $allowed_roles ) ) {
			unset( $gateways[ $id ] );
		}
	}
	return $gateways;
}
